/**
 * Deterministic 100-sample amplitude fixtures.
 *
 * These two arrays are the byte-for-byte output of
 * `createMockAmplitudeStream('listening', { seed: 42 }).next()` and
 * `createMockAmplitudeStream('speaking',  { seed: 42 }).next()` over
 * the first 100 ticks. The arrays exist so renderer e2e tests (Plan
 * 11-02 Task 2: `circle-amplitude.spec.ts`) can pre-compute the
 * expected `--circle-scale = 0.9 + amplitude * 0.5` values WITHOUT
 * re-running the LCG-driven generator inside the page context (where
 * it might not be available or might drift across re-runs).
 *
 * Regeneration recipe (if the LCG seed convention ever changes):
 *
 *   import { createMockAmplitudeStream } from
 *     '../../src/main/mock-amplitude.js';
 *   const stream = createMockAmplitudeStream('listening', { seed: 42 });
 *   const fixture: number[] = [];
 *   for (let i = 0; i < 100; i++) fixture.push(stream.next());
 *
 * Note: this file lives under `test/fixtures/` so it is NOT shipped in
 * the renderer production bundle. The e2e specs import it via a
 * relative path; the headless Vite preview bundles the fixture into
 * the test page via Playwright's `page.evaluate` argument-passing.
 */

